-- Function: public.fn_get_parent_authorized_children
-- Backup generated on 2026-10-25 20:33:35

CREATE OR REPLACE FUNCTION public.fn_get_parent_authorized_children(p_tenant_id uuid, p_user_id uuid)  RETURNS TABLE(child_id uuid, tenant_id uuid, first_name character varying, last_name character varying, date_of_birth date, classroom_id uuid, classroom_name character varying, branch_id uuid, branch_name character varying, organization_id uuid, organization_name character varying, photo_url text, relationship character varying, is_primary boolean)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT          c.id AS child_id,         c.tenant_id,         c.first_name,         c.last_name,         c.date_of_birth,         c.classroom_id,         cl.name::VARCHAR AS classroom_name,         cl.branch_id,         b.name::VARCHAR AS branch_name,         COALESCE(b.organization_id, o.id, (SELECT o2.id FROM organizations o2 WHERE o2.tenant_id = c.tenant_id ORDER BY o2.created_at LIMIT 1)) AS organization_id,         o.name::VARCHAR AS organization_name,         c.photo_url,         fr.relationship::VARCHAR,         fr.is_primary     FROM family_relationships fr     JOIN children c ON fr.child_id = c.id     LEFT JOIN classrooms cl ON c.classroom_id = cl.id     LEFT JOIN branches b ON cl.branch_id = b.id     LEFT JOIN organizations o ON b.organization_id = o.id     WHERE fr.user_id = p_user_id        AND fr.status = 'Verified' AND fr.revoked_at IS NULL       AND c.is_active = true     ORDER BY c.first_name, c.last_name; END; $function$ ;
